"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { DictionaryList } from "@/components/analysis/dictionary-list";
import { DictionarySummary } from "@/components/analysis/dictionary-summary";
import { SynonymSearch } from "@/components/analysis/synonym-search";
import { AnalysisTestSimulator } from "@/components/analysis/analysis-test-simulator";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  BookOpen,
  Search,
  LayoutDashboard,
  FileText,
  Languages,
  Hash,
  ArrowLeftRight,
  Scale,
  Space,
  Puzzle,
  FlaskConical,
  Settings,
} from "lucide-react";
import type { DictionaryType } from "@/types";
import { DICTIONARY_TYPE_LABELS } from "@/types";

type MenuSection = 'search' | 'summary' | 'test' | DictionaryType;

interface MenuItem {
  id: MenuSection;
  label: string;
  icon: React.ElementType;
  badge?: string;
}

const dictionaryMenuItems: MenuItem[] = [
  { id: 'STOP', label: '불용어', icon: FileText },
  { id: 'USER', label: '사용자 단어', icon: BookOpen },
  { id: 'ENGLISH', label: '영문 단어', icon: Languages },
  { id: 'UNIT', label: '단위', icon: Hash },
  { id: 'SYNONYM', label: '동의어', icon: ArrowLeftRight },
  { id: 'UNIT_SYNONYM', label: '단위 동의어', icon: Scale },
  { id: 'SPACE', label: '공백 분리', icon: Space },
  { id: 'COMPOUND', label: '복합어', icon: Puzzle },
];

const utilityMenuItems: MenuItem[] = [
  { id: 'search', label: '사전 조회', icon: Search },
  { id: 'test', label: '분석 테스트', icon: FlaskConical },
  { id: 'summary', label: '요약/컴파일', icon: Settings },
];

export default function DictionaryPage() {
  const [activeMenu, setActiveMenu] = useState<MenuSection>('SYNONYM');

  const isDictionaryType = (menu: MenuSection): menu is DictionaryType => {
    return dictionaryMenuItems.some(item => item.id === menu);
  };

  const renderContent = () => {
    switch (activeMenu) {
      case 'search':
        return <SynonymSearch />;
      case 'summary':
        return <DictionarySummary />;
      case 'test':
        return <AnalysisTestSimulator />;
      default:
        if (isDictionaryType(activeMenu)) {
          return <DictionaryList type={activeMenu} />;
        }
        return null;
    }
  };

  const getActiveLabel = () => {
    const allItems = [...dictionaryMenuItems, ...utilityMenuItems];
    const item = allItems.find(i => i.id === activeMenu);
    return item?.label || '';
  };

  return (
    <div className="flex h-[calc(100vh-8rem)] gap-6">
      {/* Sidebar Navigation */}
      <aside className="w-56 flex-shrink-0 space-y-1">
        <div className="flex items-center gap-2 px-3 py-2 mb-4">
          <BookOpen className="h-5 w-5 text-primary" />
          <h2 className="font-semibold">사전 관리</h2>
        </div>

        {/* Dictionary Types */}
        <div className="space-y-1">
          {dictionaryMenuItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeMenu === item.id;
            return (
              <Button
                key={item.id}
                variant={isActive ? "secondary" : "ghost"}
                className={cn(
                  "w-full justify-start gap-2 h-9",
                  isActive && "bg-secondary font-medium"
                )}
                onClick={() => setActiveMenu(item.id)}
              >
                <Icon className="h-4 w-4" />
                <span className="flex-1 text-left">{item.label}</span>
              </Button>
            );
          })}
        </div>

        <Separator className="my-4" />

        {/* Utility Menu */}
        <div className="space-y-1">
          <p className="px-3 py-1 text-xs font-medium text-muted-foreground uppercase tracking-wider">
            도구
          </p>
          {utilityMenuItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeMenu === item.id;
            return (
              <Button
                key={item.id}
                variant={isActive ? "secondary" : "ghost"}
                className={cn(
                  "w-full justify-start gap-2 h-9",
                  isActive && "bg-secondary font-medium"
                )}
                onClick={() => setActiveMenu(item.id)}
              >
                <Icon className="h-4 w-4" />
                <span className="flex-1 text-left">{item.label}</span>
              </Button>
            );
          })}
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden">
        <div className="h-full flex flex-col">
          {/* Header */}
          <div className="flex items-center justify-between pb-4 border-b">
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold tracking-tight">
                {getActiveLabel()}
              </h1>
              {isDictionaryType(activeMenu) && (
                <Badge variant="outline" className="text-xs">
                  {DICTIONARY_TYPE_LABELS[activeMenu]}
                </Badge>
              )}
            </div>
          </div>

          {/* Content Area */}
          <div className="flex-1 overflow-auto py-4">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
}

