"use client";

import { useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Plus,
  Trash2,
  Download,
  Upload,
  RefreshCw,
  MoreVertical,
  Search,
  Eye,
  Pencil,
  ArrowLeftRight,
  ArrowRight,
  Loader2,
  AlertCircle,
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { AddDictionaryDialog, EditDictionaryDialog, FileUploadDialog } from "./dictionary-dialogs";
import { useDictionaries, useDeleteDictionary, useDownloadDictionary, useResetDictionary } from "@/hooks/use-analysis";
import type { DictionaryType, Dictionary } from "@/types";
import { DICTIONARY_CATEGORY_MAP } from "@/types";
import { toast } from "sonner";

interface DictionaryListProps {
  type: DictionaryType;
}

export function DictionaryList({ type }: DictionaryListProps) {
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedRows, setSelectedRows] = useState<string[]>([]);
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<Dictionary | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [resetDialogOpen, setResetDialogOpen] = useState(false);

  // Search state
  const [searchValue, setSearchValue] = useState("");
  const [searchField, setSearchField] = useState<'all' | 'keyword' | 'value'>('all');
  const [wordMatch, setWordMatch] = useState(false);
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);

  // Active search (only updates on Enter or button click)
  const [activeSearch, setActiveSearch] = useState("");

  const category = DICTIONARY_CATEGORY_MAP[type];

  // API hooks
  const { data, isLoading, isError, refetch } = useDictionaries({
    type,
    page,
    pageSize,
    search: activeSearch || undefined,
    searchField,
    wordMatch,
  });

  const deleteMutation = useDeleteDictionary();
  const downloadMutation = useDownloadDictionary(type);
  const resetMutation = useResetDictionary();

  const items = data?.items || [];
  const total = data?.total || 0;
  const totalPages = data?.totalPages || 1;

  const handleSearch = () => {
    setPage(1);
    setActiveSearch(searchValue);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const toggleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedRows(items.map((row) => row.id));
    } else {
      setSelectedRows([]);
    }
  };

  const toggleSelectRow = (id: string, checked: boolean) => {
    if (checked) {
      setSelectedRows((prev) => [...prev, id]);
    } else {
      setSelectedRows((prev) => prev.filter((rowId) => rowId !== id));
    }
  };

  const handleEdit = (item: Dictionary) => {
    setEditingItem(item);
    setEditDialogOpen(true);
  };

  const handleDeleteSelected = async () => {
    try {
      await deleteMutation.mutateAsync({ type, ids: selectedRows });
      setSelectedRows([]);
      setDeleteDialogOpen(false);
      toast.success(`${selectedRows.length}개 항목이 삭제되었습니다.`);
    } catch (error) {
      toast.error('삭제 중 오류가 발생했습니다.');
    }
  };

  const handleDownload = async () => {
    try {
      const blob = await downloadMutation.mutateAsync();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${type.toLowerCase()}_dictionary.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      toast.success('다운로드가 시작되었습니다.');
    } catch (error) {
      toast.error('다운로드 중 오류가 발생했습니다.');
    }
  };

  const handleReset = async () => {
    try {
      await resetMutation.mutateAsync(type);
      setResetDialogOpen(false);
      toast.success('사전이 초기화되었습니다.');
    } catch (error) {
      toast.error('초기화 중 오류가 발생했습니다.');
    }
  };

  // Determine if this is a SYNONYM type to show direction
  const isSynonymType = category === 'SYNONYM';
  const isSetType = category === 'SET';
  const isMapType = category === 'MAP';

  // Get direction from dictionary item (bidirectional if keyword is null)
  const getDirection = (item: Dictionary) => {
    return item.keyword === null ? 'bidirectional' : 'unidirectional';
  };

  // Render value as badges
  const renderValueBadges = (value: string) => {
    const parts = value.split(',').map(v => v.trim()).filter(Boolean);
    return (
      <div className="flex flex-wrap gap-1">
        {parts.map((part, i) => (
          <Badge key={i} variant="secondary" className="text-xs font-normal">
            {part}
          </Badge>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-4 bg-card p-4 border rounded-lg">
        <div className="flex items-center gap-2">
          <Select value={searchField} onValueChange={(v) => setSearchField(v as 'all' | 'keyword' | 'value')}>
            <SelectTrigger className="w-[120px]">
              <SelectValue placeholder="필터" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">전체</SelectItem>
              {!isSetType && <SelectItem value="keyword">Keyword</SelectItem>}
              <SelectItem value="value">{isSetType ? '단어' : 'Value'}</SelectItem>
            </SelectContent>
          </Select>
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="검색어 입력 (Enter)"
              className="pl-9 w-[200px]"
              value={searchValue}
              onChange={(e) => setSearchValue(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>
          <div className="flex items-center space-x-2">
            <Checkbox
              id="word-match"
              checked={wordMatch}
              onCheckedChange={(checked) => setWordMatch(!!checked)}
            />
            <label htmlFor="word-match" className="text-sm font-medium">
              단어매칭
            </label>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {!isEditMode ? (
            <Button
              variant="outline"
              size="sm"
              onClick={handleDownload}
              disabled={downloadMutation.isPending}
            >
              {downloadMutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Download className="mr-2 h-4 w-4" />
              )}
              Download
            </Button>
          ) : (
            <>
              <Button size="sm" onClick={() => setAddDialogOpen(true)}>
                <Plus className="mr-2 h-4 w-4" />
                추가
              </Button>
              <Button
                variant="destructive"
                size="sm"
                disabled={selectedRows.length === 0}
                onClick={() => setDeleteDialogOpen(true)}
              >
                <Trash2 className="mr-2 h-4 w-4" />
                삭제 ({selectedRows.length})
              </Button>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="sm">
                    <MoreVertical className="mr-2 h-4 w-4" />
                    더보기
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent>
                  <DropdownMenuItem onClick={() => setUploadDialogOpen(true)}>
                    <Upload className="mr-2 h-4 w-4" />
                    파일 업로드
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem
                    className="text-destructive"
                    onClick={() => setResetDialogOpen(true)}
                  >
                    사전 초기화
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </>
          )}
          <Button
            variant="outline"
            size="sm"
            onClick={() => refetch()}
            disabled={isLoading}
          >
            <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
          </Button>
          <Button
            variant={isEditMode ? "secondary" : "outline"}
            size="sm"
            onClick={() => {
              setIsEditMode(!isEditMode);
              setSelectedRows([]);
            }}
          >
            {isEditMode ? (
              <><Eye className="mr-2 h-4 w-4" />보기</>
            ) : (
              <><Pencil className="mr-2 h-4 w-4" />수정</>
            )}
          </Button>
        </div>
      </div>

      {/* Table */}
      <div className="rounded-md border bg-background">
        {isLoading ? (
          <div className="flex items-center justify-center h-64">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        ) : isError ? (
          <div className="flex flex-col items-center justify-center h-64 text-muted-foreground">
            <AlertCircle className="h-8 w-8 mb-2" />
            <p>데이터를 불러오는데 실패했습니다.</p>
            <Button variant="link" onClick={() => refetch()}>다시 시도</Button>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                {isEditMode && (
                  <TableHead className="w-[50px]">
                    <Checkbox
                      checked={selectedRows.length === items.length && items.length > 0}
                      onCheckedChange={(checked) => toggleSelectAll(!!checked)}
                    />
                  </TableHead>
                )}

                {/* SET Type: Just "단어" column */}
                {isSetType && (
                  <>
                    <TableHead>단어</TableHead>
                    <TableHead className="w-[150px]">등록일</TableHead>
                  </>
                )}

                {/* SYNONYM Type: Direction, Representative, Synonyms */}
                {isSynonymType && (
                  <>
                    <TableHead className="w-[60px]">방향</TableHead>
                    <TableHead className="w-[150px]">대표어</TableHead>
                    <TableHead>동의어</TableHead>
                    <TableHead className="w-[120px]">등록일</TableHead>
                  </>
                )}

                {/* MAP Type: Original, Arrow, Result */}
                {isMapType && (
                  <>
                    <TableHead className="w-[200px]">
                      {type === 'SPACE' ? '붙여쓴 말' : '복합어'}
                    </TableHead>
                    <TableHead className="w-[40px]"></TableHead>
                    <TableHead>
                      {type === 'SPACE' ? '분리 결과' : '분해 결과'}
                    </TableHead>
                    <TableHead className="w-[120px]">등록일</TableHead>
                  </>
                )}

                {isEditMode && <TableHead className="text-right w-[100px]">액션</TableHead>}
              </TableRow>
            </TableHeader>
            <TableBody>
              {items.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={isEditMode ? 5 : 4}
                    className="text-center text-muted-foreground h-32"
                  >
                    등록된 데이터가 없습니다.
                  </TableCell>
                </TableRow>
              ) : items.map((item) => (
                <TableRow key={item.id}>
                  {isEditMode && (
                    <TableCell>
                      <Checkbox
                        checked={selectedRows.includes(item.id)}
                        onCheckedChange={(checked) => toggleSelectRow(item.id, !!checked)}
                      />
                    </TableCell>
                  )}

                  {/* SET Type Cells */}
                  {isSetType && (
                    <>
                      <TableCell className="font-medium">{item.value}</TableCell>
                      <TableCell className="text-muted-foreground text-sm">
                        {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
                      </TableCell>
                    </>
                  )}

                  {/* SYNONYM Type Cells */}
                  {isSynonymType && (
                    <>
                      <TableCell>
                        {getDirection(item) === 'bidirectional' ? (
                          <ArrowLeftRight className="h-4 w-4 text-blue-500" />
                        ) : (
                          <ArrowRight className="h-4 w-4 text-green-500" />
                        )}
                      </TableCell>
                      <TableCell className="font-medium">
                        {item.keyword || <span className="text-muted-foreground">-</span>}
                      </TableCell>
                      <TableCell>{renderValueBadges(item.value)}</TableCell>
                      <TableCell className="text-muted-foreground text-sm">
                        {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
                      </TableCell>
                    </>
                  )}

                  {/* MAP Type Cells */}
                  {isMapType && (
                    <>
                      <TableCell className="font-medium">{item.keyword}</TableCell>
                      <TableCell>
                        <ArrowRight className="h-4 w-4 text-muted-foreground" />
                      </TableCell>
                      <TableCell>{renderValueBadges(item.value)}</TableCell>
                      <TableCell className="text-muted-foreground text-sm">
                        {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
                      </TableCell>
                    </>
                  )}

                  {isEditMode && (
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEdit(item)}
                      >
                        수정
                      </Button>
                    </TableCell>
                  )}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between">
        <div className="text-sm text-muted-foreground">
          총 {total.toLocaleString()}건 중 {((page - 1) * pageSize) + 1} - {Math.min(page * pageSize, total)}
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            disabled={page <= 1}
            onClick={() => setPage(p => p - 1)}
          >
            이전
          </Button>
          <span className="text-sm px-2">
            {page} / {totalPages}
          </span>
          <Button
            variant="outline"
            size="sm"
            disabled={page >= totalPages}
            onClick={() => setPage(p => p + 1)}
          >
            다음
          </Button>
        </div>
      </div>

      {/* Dialogs */}
      <AddDictionaryDialog
        open={addDialogOpen}
        onOpenChange={setAddDialogOpen}
        type={type}
      />

      <EditDictionaryDialog
        open={editDialogOpen}
        onOpenChange={setEditDialogOpen}
        type={type}
        item={editingItem}
      />

      <FileUploadDialog
        open={uploadDialogOpen}
        onOpenChange={setUploadDialogOpen}
        type={type}
      />

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>삭제 확인</AlertDialogTitle>
            <AlertDialogDescription>
              선택한 {selectedRows.length}개 항목을 삭제하시겠습니까?
              이 작업은 되돌릴 수 없습니다.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>취소</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDeleteSelected}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleteMutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : null}
              삭제
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Reset Confirmation */}
      <AlertDialog open={resetDialogOpen} onOpenChange={setResetDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>사전 초기화</AlertDialogTitle>
            <AlertDialogDescription>
              모든 데이터가 삭제됩니다. 정말 초기화하시겠습니까?
              이 작업은 되돌릴 수 없습니다.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>취소</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleReset}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {resetMutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : null}
              초기화
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

