```typescript
import axios from 'axios';
import { useAuthStore } from '@/stores/auth.store';

// Separate client for dictionary service (search-admin backend)
const dictionaryClient = axios.create({
  baseURL: process.env.NEXT_PUBLIC_DICTIONARY_API_URL || 'http://localhost:8080/api/v1/dictionary',
  timeout: 30000,
});

dictionaryClient.interceptors.request.use((config) => {
  const { token } = useAuthStore.getState();
  if (token) {
    config.headers['Authorization'] = `Bearer ${token}`;
  }
  return config;
});

dictionaryClient.interceptors.response.use(
  (response) => response,
  (error) => {
    // Centralized error handling
    if (error.response?.status === 401) {
      // Handle unauthorized
    }
    return Promise.reject(error);
  }
);

export default dictionaryClient;
```

