#### 3.4 Type Mapping Utilities

**File**: `/src/lib/api/dictionary-mapper.ts`

```typescript
import type { Dictionary, PaginatedResponse } from '@/types';
import type { DictionaryWithId, BackendPaginatedResponse } from '@/types/dictionary';

/**
 * Transform backend DTO to frontend model
 */
export function mapDictionaryFromBackend(dto: DictionaryWithId): Dictionary {
  return {
    id: String(dto.id),
    type: dto.dictionary.type,
    keyword: dto.dictionary.keyword || null,
    value: dto.dictionary.value,
    createdAt: dto.dictionary.createdTime,
    updatedAt: dto.dictionary.updatedTime,
  };
}

/**
 * Transform paginated response from backend format to frontend format
 */
export function mapPaginatedResponse<T, R>(
  response: BackendPaginatedResponse<T>,
  mapper: (item: T) => R
): PaginatedResponse<R> {
  return {
    items: response.content.map(mapper),
    total: response.totalElements,
    page: response.number + 1, // Convert 0-based to 1-based
    pageSize: response.size,
    totalPages: response.totalPages,
  };
}
```

### Phase 3: React Query Hooks

#### 3.5 Create Dictionary Hooks (Backend Version)

**File**: `/src/hooks/use-dictionary.ts` (new file)

```typescript
'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import dictionaryClient from '@/lib/api/dictionary-client';
import { mapDictionaryFromBackend, mapPaginatedResponse } from '@/lib/api/dictionary-mapper';
import type { DictionaryType, Dictionary, PaginatedResponse } from '@/types';
import type {
  DictionaryWithId,
  BackendPaginatedResponse,
  CompileResult,
  CreateDictionaryRequest,
  UpdateDictionaryRequest,
} from '@/types/dictionary';

// ========================================
// Query Keys
// ========================================

export const dictionaryKeys = {
  all: ['dictionary'] as const,
  lists: () => [...dictionaryKeys.all, 'list'] as const,
  list: (type: DictionaryType, page: number, size: number) =>
    [...dictionaryKeys.lists(), type, { page, size }] as const,
  search: (type: DictionaryType, word: string, isMatch: boolean) =>
    [...dictionaryKeys.all, 'search', type, { word, isMatch }] as const,
  compile: () => [...dictionaryKeys.all, 'compile'] as const,
  compileType: (type: DictionaryType) => [...dictionaryKeys.compile(), type] as const,
};

// ========================================
// List & Search Hooks
// ========================================

interface UseDictionaryListParams {
  type: DictionaryType;
  page?: number;
  size?: number;
  enabled?: boolean;
}

/**
 * Fetch paginated dictionary entries by type
 */
export function useDictionaryList({
  type,
  page = 0,
  size = 20,
  enabled = true,
}: UseDictionaryListParams) {
  return useQuery({
    queryKey: dictionaryKeys.list(type, page, size),
    queryFn: async (): Promise<PaginatedResponse<Dictionary>> => {
      const response = await dictionaryClient.get<BackendPaginatedResponse<DictionaryWithId>>(
        `/${type}`,
        { params: { page, size } }
      );
      return mapPaginatedResponse(response.data, mapDictionaryFromBackend);
    },
    enabled,
    staleTime: 30000,
  });
}

interface UseDictionarySearchParams {
  type: DictionaryType;
  word: string;
  isMatch?: boolean;
  enabled?: boolean;
}

/**
 * Search dictionary entries
 */
export function useDictionarySearch({
  type,
  word,
  isMatch = true,
  enabled = true,
}: UseDictionarySearchParams) {
  return useQuery({
    queryKey: dictionaryKeys.search(type, word, isMatch),
    queryFn: async () => {
      const response = await dictionaryClient.get<DictionaryWithId[]>(
        `/${type}/search`,
        { params: { word, isMatch } }
      );
      return response.data.map(mapDictionaryFromBackend);
    },
    enabled: enabled && word.length > 0,
    staleTime: 30000,
  });
}

// ========================================
// CRUD Mutations
// ========================================

/**
 * Create a new dictionary entry
 */
export function useCreateDictionaryEntry() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: CreateDictionaryRequest) => {
      const response = await dictionaryClient.post<DictionaryWithId>('/', params);
      return mapDictionaryFromBackend(response.data);
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
    },
  });
}

interface UpdateDictionaryParams extends UpdateDictionaryRequest {
  id: string;
}

/**
 * Update an existing dictionary entry
 */
export function useUpdateDictionaryEntry() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...params }: UpdateDictionaryParams) => {
      const response = await dictionaryClient.put<DictionaryWithId>(`/${id}`, params);
      return mapDictionaryFromBackend(response.data);
    },
    onSuccess: (result) => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
    },
  });
}

/**
 * Delete a dictionary entry
 */
export function useDeleteDictionaryEntry() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string) => {
      await dictionaryClient.delete(`/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.lists(),
      });
    },
  });
}

// ========================================
// Compile Operations
// ========================================

/**
 * Compile a single dictionary type
 */
export function useCompileDictionaryType() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (type: DictionaryType): Promise<CompileResult> => {
      const response = await dictionaryClient.post<CompileResult>(`/compile/${type}`);
      return response.data;
    },
    onSuccess: (_, type) => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.compileType(type),
      });
    },
  });
}

/**
 * Compile all dictionary types
 */
export function useCompileAllDictionaries() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (): Promise<CompileResult[]> => {
      const response = await dictionaryClient.post<CompileResult[]>('/compile');
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: dictionaryKeys.compile(),
      });
    },
  });
}
```

